def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n-1)

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_max(arr):
    m = arr[0]
    for x in arr:
        if x > m:
            m = x
    return m

def char_count(s):
    freq = {}
    for c in s:
        freq[c] = freq.get(c, 0) + 1
    return freq
